<?php
declare(strict_types=1);
$page_title='Notificações';require_once __DIR__ . '/../includes/header.php';$user=current_user();$page=max(1,(int)($_GET['pagina']??1));$perPage=15;$offset=($page-1)*$perPage;$count=db()->prepare('SELECT COUNT(*) FROM notificacoes WHERE usuario_id=?');$count->execute([$user['id']]);$total=(int)$count->fetchColumn();$stmt=db()->prepare('SELECT * FROM notificacoes WHERE usuario_id=? ORDER BY created_at DESC LIMIT ? OFFSET ?');$stmt->bindValue(1,$user['id'],PDO::PARAM_INT);$stmt->bindValue(2,$perPage,PDO::PARAM_INT);$stmt->bindValue(3,$offset,PDO::PARAM_INT);$stmt->execute();$items=$stmt->fetchAll();
?>
<div class="section-heading"><div><h2>Central de notificações</h2><p><?= $total ?> registro(s) para sua conta.</p></div><form method="post" action="<?=e(url('notificacoes/marcar-lida.php'))?>" class="no-print"><?=csrf_input()?><input type="hidden" name="all" value="1"><button class="btn btn-secondary" data-confirm="Marcar todas as notificações como lidas?">Marcar todas como lidas</button></form></div>
<div class="notification-list"><?php foreach($items as $n):?><form method="post" action="<?=e(url('notificacoes/marcar-lida.php'))?>" class="notification-item <?=!$n['lida_em']?'unread':''?>"><?=csrf_input()?><input type="hidden" name="id" value="<?= (int)$n['id'] ?>"><button type="submit" class="notification-button"><strong><?=e($n['titulo'])?></strong><p><?=e($n['mensagem'])?></p><small><?=date_br($n['created_at'],true)?> <?=!$n['lida_em']?'· Não lida':''?></small></button></form><?php endforeach;?><?php if(!$items):?><div class="card empty-state"><i class="fa-regular fa-bell-slash"></i>Você não tem notificações.</div><?php endif;?></div>
<?php if($total>$perPage):?><nav class="pagination" aria-label="Paginação"><?php for($i=1;$i<=ceil($total/$perPage);$i++):?><a class="<?=$i===$page?'active':''?>" href="?pagina=<?=$i?>"><?=$i?></a><?php endfor;?></nav><?php endif;?>
<?php require_once __DIR__ . '/../includes/footer.php'; ?>
